package com.bank.suffix;

import java.util.*;
import java.util.logging.Logger;

public class SuffixDemo {
    private static final Logger log = Logger.getLogger(SuffixDemo.class.getName());

    public static void main(String[] args) {
        int[] assigned = {2, 3, 4};   // in-range suffixes already used
        int k = 3;
        log.info("Assigned suffixes: " + Arrays.toString(assigned) + ", need k=" + k);

        SuffixAllocator allocator = new SuffixAllocator();
        List<Integer> freeSuffixes = allocator.firstKMissing(assigned, k);

        log.info("First " + k + " free suffixes: " + freeSuffixes);
    }
}
