package com.bank.suffix;

import java.util.*;

public class SuffixAllocator {

    public List<Integer> firstKMissing(int[] nums, int k) {
        int i = 0, n = nums.length;
        // Cyclic placement of in-range positives.
        while (i < n) {
            int v = nums[i];
            if (v > 0 && v <= n && nums[i] != nums[v - 1]) {
                int tmp = nums[i]; nums[i] = nums[v - 1]; nums[v - 1] = tmp;
            } else {
                i++;
            }
        }
        List<Integer> missing = new ArrayList<>();
        Set<Integer> strays = new HashSet<>();        // existing numbers > n or dups
        // Emit empty homes as missing; remember the stray value that sits there.
        for (int idx = 0; idx < n && missing.size() < k; idx++) {
            if (nums[idx] != idx + 1) {
                missing.add(idx + 1);
                strays.add(nums[idx]);
            }
        }
        // Extend past n, skipping numbers that actually exist.
        for (int c = n + 1; missing.size() < k; c++) {
            if (!strays.contains(c)) missing.add(c);
        }
        return missing;
    }
}
